import numpy as np, itertools
base={'1':np.ones_like(P),'P':P,'P2':P**2,'P3':P**3,'sqP':np.sqrt(P),'P1.5':P**1.5}
tb={'1':np.ones_like(t),'sqt':np.sqrt(t),'t':t,'ln1pt':np.log1p(t)}
cross={'P*t':P*t,'P/t':P/t,'P+t':P+t,'P*sqt':P*np.sqrt(t),'P/sqt':P/np.sqrt(t),'P*sq1t':P*np.sqrt(1+t),'P/(1+t)':P/(1+t)}
fns={'id':lambda x:x,'sqrt':np.sqrt,'log':np.log,'exp-':lambda x:np.exp(-x),'inv':lambda x:1/x,'sq':lambda x:x**2}
feats={}
for bn,bv in base.items():
  for tn_,tv in tb.items(): feats[f'{bn}*{tn_}']=bv*tv
for cn,cv in cross.items():
  for fn,f in fns.items():
    with np.errstate(all='ignore'):
      v=f(cv)
    if np.all(np.isfinite(v)): feats[f'[{fn}({cn})]']=v
names=list(feats.keys()); M=np.column_stack([feats[n] for n in names])
