sel=[];best=None
y=dP_dt
for step in range(8):
    bestc=None
    for j,n in enumerate(names):
        if j in sel: continue
        A=M[:,sel+[j]]
        cc,_,_,_=np.linalg.lstsq(A,y,rcond=None)
